import sys

def resolve_type(t, types):
    while t in types:
        t = types[t]
    return t

def apply_dereference(t):
    if t == 'void':
        return 'errtype'
    elif t == 'errtype':
        return 'errtype'
    elif t.endswith('*'):
        return t[:-1]
    else:
        return 'errtype'

def apply_pointer(t):
    return t + '*'

n = int(sys.stdin.readline())
types = {}
results = []

for _ in range(n):
    line = sys.stdin.readline().strip()
    if line.startswith('typedef'):
        _, a, b = line.split()
        a = resolve_type(a, types)
        types[b] = a
    elif line.startswith('typeof'):
        _, a = line.split()
        a = resolve_type(a, types)
        asterisks = 0
        while a.endswith('*'):
            asterisks += 1
            a = a[:-1]
        if a == '&':
            a = 'void'
        if a != 'void':
            results.append('errtype')
        else:
            results.append('void' + '*' * asterisks)

for result in results:
    print(result)
